            }
            lock (Gate)
            {
                System.IO.File.AppendAllText(System.IO.Path.Combine(folder, CheckedName), line + "\n");
            }
        }

        private static System.IO.MemoryMappedFiles.MemoryMappedViewAccessor OpenControl()
