                controlActivated = Part(parts, 3);
                controlPlanned = Part(parts, 4);
                controlPlan = controlPlanned != null && controlPlanned != "*" ? ReadPlanFile(controlPlanned) : null;
                System.Threading.Volatile.Write(ref controlRun, run);
            }
        }

