            {
                var context = System.Type.GetType("NUnit.Framework.TestContext, nunit.framework", false);
                var current = context == null ? null : context.GetProperty("CurrentContext");
                var test = context == null ? null : context.GetProperty("Test");
                return current == null || test == null ? null : NUnitName(current, test);
            }
            catch
            {
                return null;
            }
        }

        private static System.Func<string> NUnitName(System.Reflection.PropertyInfo current, System.Reflection.PropertyInfo test)
        {
            var method = test.PropertyType.GetProperty("MethodName");
            var fullName = test.PropertyType.GetProperty("FullName");
            if (method == null || fullName == null)
            {
                return null;
            }
            var running = System.Linq.Expressions.Expression.Variable(test.PropertyType, "test");
            var body = System.Linq.Expressions.Expression.Block(
                new[] { running },
                System.Linq.Expressions.Expression.Assign(
                    running,
                    System.Linq.Expressions.Expression.Property(System.Linq.Expressions.Expression.Property(null, current), test)),
                System.Linq.Expressions.Expression.Condition(
                    System.Linq.Expressions.Expression.Equal(
                        System.Linq.Expressions.Expression.Property(running, method),
                        System.Linq.Expressions.Expression.Constant(null, typeof(string))),
                    System.Linq.Expressions.Expression.Constant(""),
                    System.Linq.Expressions.Expression.Property(running, fullName)));
            return System.Linq.Expressions.Expression.Lambda<System.Func<string>>(body).Compile();
        }

        private static readonly System.Collections.Concurrent.ConcurrentDictionary<int, bool> RunOnce =
            new System.Collections.Concurrent.ConcurrentDictionary<int, bool>();

        /// Reached while no test is known (the adapter reports a test's start
        /// from another thread, sometimes after the test began; class fixtures
        /// run before it): dog-food's collector or worker gives these mutants
        /// to the test that starts next. Code that runs once stays outside.
        private static void Pending(int id, bool runsOnce)
        {
            var domain = System.AppDomain.CurrentDomain;
            var pending = domain.GetData("DgfPending") as System.Collections.Concurrent.ConcurrentDictionary<int, bool>;
            if (pending == null)
            {
                lock (Gate)
                {
                    pending = domain.GetData("DgfPending") as System.Collections.Concurrent.ConcurrentDictionary<int, bool>;
                    if (pending == null)
                    {
                        pending = new System.Collections.Concurrent.ConcurrentDictionary<int, bool>();
                        domain.SetData("DgfPending", pending);
                    }
                }
            }
            if (pending.ContainsKey(id) || RunOnce.ContainsKey(id))
            {
                return;
            }
            if (runsOnce)
            {
                RunOnce.TryAdd(id, true);
            }
            else
            {
                pending.TryAdd(id, true);
            }
        }

        /// Hits per test and mutant in a run that records reach: the stack
        /// is read on the first hit and then at 2, 4, 8 ... 1024, so a site
        /// reached from ordinary code first and from a static constructor
        /// later in the same test is still found, at a bounded cost.
        private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> Hits =
            new System.Collections.Concurrent.ConcurrentDictionary<string, int>();

        private static void Record(string file, string test, int id)
        {
            var key = test + "\t" + id;
            var hits = Hits.AddOrUpdate(key, 1, (_, n) => n + 1);
            if (!WalksAt(hits))
            {
                return;
            }
            var kind = RunsOnceKind();
            if (test.Length == 0)
            {
                Pending(id, kind != null);
            }
            if (!Seen.TryAdd(key + "\t" + (kind ?? ""), true))
            {
                return;
            }
            lock (Gate)
            {
                System.IO.File.AppendAllText(file, ReachLine(test, id, kind));
            }
        }

        /// The stack is read at hits 1, 2, 4, ... 1024 of a test and mutant.
        private static bool WalksAt(int hits)
        {
            return hits <= 1024 && (hits & (hits - 1)) == 0;
        }

        /// Reached in code that runs once for every test after it: outside
        /// any test, with the test it ran in and the kind after the id. A
        /// static constructor ("cctor") runs once per process, whatever
        /// tests it is first seen in; a lazy fill ("lazy") that dgf finds
        /// in two tests of one process runs for each test.
        private static string ReachLine(string test, int id, string kind)
        {
            return test.Length > 0 && kind != null
                ? "\t" + id + "\t" + test + "\t" + kind + "\n"
                : test + "\t" + id + "\n";
        }

        /// What code that runs once for every test after it is on the stack:
        /// "cctor" for a static constructor (field initializers are part of
        /// it) of another type, "lazy" for a lazy cache filling a value on
        /// first use, null for neither. A static constructor counts over a
        /// lazy fill inside it. Every frame is read: with inlining, skipping
        /// a fixed number could skip it.
        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        private static string RunsOnceKind()
        {
            var frames = new System.Diagnostics.StackTrace(false).GetFrames();
            if (frames == null)
            {
                return null;
            }
            string kind = null;
            foreach (var frame in frames)
            {
                var found = RunsOnce(frame.GetMethod());
                if (found == "cctor")
                {
                    return found;
                }
                kind = kind ?? found;
            }
            return kind;
        }

        /// "cctor" for a static constructor, "lazy" for a lazy cache, other
        /// than dog-food's own; null otherwise.
        private static string RunsOnce(System.Reflection.MethodBase method)
        {
            if (method == null || method.DeclaringType == typeof(DgfMutants))
            {
                return null;
            }
            // IsConstructor is false for a static constructor: match its name.
            if (method.Name == System.Reflection.ConstructorInfo.TypeConstructorName)
            {
                return "cctor";
            }
            return FillsLazily(method) ? "lazy" : null;
        }

        /// Code that runs once per key or value and is cached for every caller
        /// after: ConditionalWeakTable, Lazy, LazyInitializer,
        /// ConcurrentDictionary.GetOrAdd, IMemoryCache.GetOrCreate, and EF
        /// Core building a context's model (OnModelCreating, once per process).
        private static bool FillsLazily(System.Reflection.MethodBase method)
        {
            if (method.Name == "OnModelCreating")
            {
                return true;
            }
            var type = method.DeclaringType;
            if (type == null)
            {
                return false;
            }
            var name = type.Namespace + "." + type.Name;
            string prefix;
            return LazyTypes.Contains(name) || (LazyMethods.TryGetValue(name, out prefix) && method.Name.StartsWith(prefix));
        }

        /// Types whose every method fills a value once.
        private static readonly System.Collections.Generic.HashSet<string> LazyTypes = new System.Collections.Generic.HashSet<string>
        {
            "System.Runtime.CompilerServices.ConditionalWeakTable`2",
            "System.Lazy`1",
            "System.Threading.LazyInitializer",
            "Microsoft.EntityFrameworkCore.Infrastructure.ModelSource",
        };

        /// Types where only the methods starting with a name do.
        private static readonly System.Collections.Generic.Dictionary<string, string> LazyMethods = new System.Collections.Generic.Dictionary<string, string>
        {
            { "System.Collections.Concurrent.ConcurrentDictionary`2", "GetOrAdd" },
            { "Microsoft.Extensions.Caching.Memory.CacheExtensions", "GetOrCreate" },
        };

        private static int ReadActive()
        {
            int id;
            return int.TryParse(System.Environment.GetEnvironmentVariable("DGF_MUTANT"), out id) ? id : -1;
        }

        private static System.Collections.Generic.Dictionary<string, int> ReadPlan()
        {
            return ReadPlanFile(System.Environment.GetEnvironmentVariable("DGF_PLAN"));
        }

        private static System.Collections.Generic.Dictionary<string, int> ReadPlanFile(string path)
        {
            if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path))
            {
                return null;
            }
            var plan = new System.Collections.Generic.Dictionary<string, int>();
            foreach (var line in System.IO.File.ReadAllLines(path))
            {
                var tab = line.LastIndexOf('\t');
                int id;
                if (tab > 0 && int.TryParse(line.Substring(tab + 1), out id))
                {
                    plan[line.Substring(0, tab)] = id;
                }
            }
            return plan;
        }

        private static string ReachFromEnvironment()
        {
            var folder = System.Environment.GetEnvironmentVariable("DGF_REACH");
            return string.IsNullOrEmpty(folder) ? null : folder;
        }
    }
